mapper.sql:
and (
  (r.owner_type = 1 and (
    exists (select 1 from cms_topic t
             where t.id = r.owner_id and t.member_id = #{ownerMemberId} and t.del_flag = 0)
    or exists (select 1 from cms_registration_merchant crm
               where crm.topic_id = r.owner_id and crm.member_id = #{ownerMemberId}
                 and crm.audit_status = 1 and crm.del_flag = 0)
  ))
  or (r.owner_type = 2 and exists (
    select 1 from cms_activity a
     where a.id = r.owner_id and a.member_id = #{ownerMemberId} and a.del_flag = 0
  ))
)

mapper.select:
select coalesce(sum(case when event_code = 'BROWSE' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_browse, coalesce(sum(case when event_code = 'BROWSE' and event_time >= #{previousStart} and event_time < #{currentStart} then 1 else 0 end), 0) as previous_browse, coalesce(sum(case when event_code = 'SIGNUP' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_signup, coalesce(sum(case when event_code = 'SIGNUP' and event_time >= #{previousStart} and event_time < #{currentStart} then 1 else 0 end), 0) as previous_signup, coalesce(sum(case when event_code = 'PAYMENT' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_payment, coalesce(sum(case when event_code = 'PAYMENT' and event_time >= #{previousStart} and event_time < #{currentStart} then 1 else 0 end), 0) as previous_payment, coalesce(sum(case when event_code = 'VERIFY' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_verify, coalesce(sum(case when event_code = 'VERIFY' and event_time >= #{previousStart} and event_time < #{currentStart} then 1 else 0 end), 0) as previous_verify, coalesce(sum(case when event_code = 'REFUND_APPLY' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_refund_apply, coalesce(sum(case when event_code = 'REFUND_APPLY' and event_time >= #{previousStart} and event_time < #{currentStart} then 1 else 0 end), 0) as previous_refund_apply, coalesce(sum(case when event_code = 'SIGNUP' and touchpoint_code = 'IN_APP_TOPIC' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_topic_touchpoint, coalesce(sum(case when event_code = 'SIGNUP' and touchpoint_code = 'IN_APP_ACTIVITY' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_activity_touchpoint, coalesce(sum(case when event_code = 'SIGNUP' and touchpoint_code = 'UNATTRIBUTED' and event_time >= #{currentStart} and event_time < #{endExclusive} then 1 else 0 end), 0) as current_unattributed_touchpoint from ( select 'BROWSE' as event_code, b.browse_time as event_time, null as touchpoint_code from tms_browse_record b where b.browse_time >= #{previousStart} and b.browse_time < #{endExclusive} and ( (b.browse_type = 1 and ( exists (select 1 from cms_topic t where t.id = b.target_id and t.member_id = #{ownerMemberId} and t.del_flag = 0) or exists (select 1 from cms_registration_merchant crm where crm.topic_id = b.target_id and crm.member_id = #{ownerMemberId} and crm.audit_status = 1 and crm.del_flag = 0) or exists (select 1 from cms_topic_node n where n.topic_id = b.target_id and n.merchant_member_id = #{ownerMemberId}) )) or (b.browse_type = 2 and exists ( select 1 from cms_activity a where a.id = b.target_id and a.member_id = #{ownerMemberId} and a.del_flag = 0 )) ) union all select 'SIGNUP' as event_code, r.create_time as event_time, case when r.owner_type = 1 then 'IN_APP_TOPIC' when r.owner_type = 2 then 'IN_APP_ACTIVITY' else 'UNATTRIBUTED' end as touchpoint_code from cms_registration r where r.create_time >= #{previousStart} and r.create_time < #{endExclusive}
union all select 'PAYMENT' as event_code, r.payment_time as event_time, null as touchpoint_code from cms_registration r where r.payment_time is not null and r.payment_time >= #{previousStart} and r.payment_time < #{endExclusive}
union all select 'VERIFY' as event_code, rd.create_time as event_time, null as touchpoint_code from redemption rd where rd.merchant_id = #{ownerMemberId} and rd.status = 'ACTIVE' and rd.create_time >= #{previousStart} and rd.create_time < #{endExclusive} union all select 'REFUND_APPLY' as event_code, f.create_time as event_time, null as touchpoint_code from refund_application f where f.merchant_id = #{ownerMemberId} and f.del_flag = 0 and f.create_time >= #{previousStart} and f.create_time < #{endExclusive} ) events
